package com.project.entity.enterprise;
import com.project.entity.Employee; import javax.persistence.*; import java.time.LocalDate;
@Entity @Table(name="timesheet_entries", uniqueConstraints=@UniqueConstraint(columnNames={"employee_id","work_date"})) public class TimesheetEntry { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="employee_id",nullable=false) private Employee employee; @Column(name="work_date") private LocalDate workDate; private long regularMinutes; private long overtimeMinutes; private String status="DRAFT"; public Long getId(){return id;} public Employee getEmployee(){return employee;} public void setEmployee(Employee v){employee=v;} public LocalDate getWorkDate(){return workDate;} public void setWorkDate(LocalDate v){workDate=v;} public long getRegularMinutes(){return regularMinutes;} public void setRegularMinutes(long v){regularMinutes=v;} public long getOvertimeMinutes(){return overtimeMinutes;} public void setOvertimeMinutes(long v){overtimeMinutes=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} }
